package org.dromara.sports.tables.d03.team_room;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.sports.api.EventRegistrationApi;
import org.dromara.sports.api.RoomRegistrationApi;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.time.OffsetDateTime;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;

/** Unit locks serialize seats, invitations and matching. They never reserve a formal registration quota. */
@Service @RequiredArgsConstructor
public class RoomService implements CapabilityProvider {
    private final ScopedJdbc db;
    private final ObjectMapper json;private final org.dromara.sports.api.GrowthPolicyApi growthPolicies;
    private final EventRegistrationApi events;
    private final RoomRegistrationApi registrations;
    private static final Set<String> READS=Set.of("asp_event","asp_team_room","asp_team_room_member","asp_recruitment","asp_matching_request","asp_matching_offer","asp_matching_offer_member","asp_room_interaction","asp_competition_type","asp_competition_unit","asp_sport","asp_account","asp_person","asp_team","asp_team_member","asp_profile_display","asp_growth_profile","asp_growth_policy","asp_title_equipment","asp_honor","asp_registration","asp_registration_member");
    private static final Set<String> WRITES=Set.of("asp_team_room","asp_team_room_member","asp_recruitment","asp_matching_request","asp_matching_offer","asp_matching_offer_member","asp_room_interaction","asp_registration","asp_registration_member","asp_notification","asp_notification_delivery","asp_idempotency");
    public List<CapabilityDefinition> capabilities(){var list=new ArrayList<CapabilityDefinition>();
        list.add(capability(json,"room.query","查询我的集结、邀请或指定项目招募","asp_team_room",true,false,Set.of("platform"),"",READS,Set.of(),"roomId?","unitId?"));
        list.add(cap("room.create","创建参赛房间",false,"unitId","name","teamId?"));
        list.add(cap("room.ready","确认我的准备状态",false,"roomId","ready","expectedVersion"));
        list.add(cap("room.announce","更新房间公告",false,"roomId","message","expectedVersion"));
        list.add(cap("room.encourage","为队友加油",false,"roomId","message"));
        list.add(cap("room.recruit","发布缺员招募",true,"roomId","message","expectedVersion"));
        list.add(cap("room.apply","申请加入招募房间",false,"roomId"));
        list.add(cap("room.match","开始自动匹配",false,"unitId","roomId?","timePreference?"));
        list.add(cap("room.stopMatch","停止我的匹配",false,"requestId"));
        list.add(cap("room.answer","本人回应组队邀请",true,"offerId","answer"));
        list.add(cap("room.leave","退出本场房间",true,"roomId","newHostAccountId?","expectedVersion"));
        list.add(cap("room.transfer","移交房主",true,"roomId","newHostAccountId","expectedVersion"));
        list.add(cap("room.prepare","准备报名和成员确认",true,"roomId","expectedVersion"));
        return list;
    }
    private CapabilityDefinition cap(String code,String title,boolean confirm,String... fields){return capability(json,code,title,"asp_team_room",!code.equals("room.answer"),confirm,Set.of("platform"),"",READS,WRITES,fields);}
    public JsonNode preview(String code,JsonNode in){if(code.equals("room.apply")){var room=load(id(in,"roomId"));return options(number(room.get("unit_id")));}if(in.has("roomId"))return detail(id(in,"roomId"));if(in.has("unitId"))return options(id(in,"unitId"));return home();}
    public JsonNode execute(String code,JsonNode in){long a=account();
        if(code.equals("room.query"))return preview(code,in);
        if(code.equals("room.create")){long unit=id(in,"unitId");db.lock("room-unit:"+unit);expire(unit);var u=openUnit(unit);free(unit,a);Long team=optionalId(in,"teamId");if(team!=null){long p=person(a);if(db.count("SELECT count(*) FROM asp_team WHERE id=? AND sport_id=? AND captain_person_id=? AND status='active'",team,u.get("sport_id"),p)==0)throw fail("请选择由你担任队长、同运动的有效队伍",403);}long room=create(unit,number(u.get("competition_type_id")),a,team,text(in,"name",100));return reference(json,"roomId",room,"forming");}
        if(code.equals("room.match"))return queue(in,a);
        if(code.equals("room.answer"))return answer(in,a);
        if(code.equals("room.stopMatch")){long request=id(in,"requestId");var r=db.one("SELECT * FROM asp_matching_request WHERE id=? AND account_id=?",request,a);if(r==null)throw fail("匹配请求不存在",404);long unit=number(r.get("unit_id"));db.lock("room-unit:"+unit);expire(unit);for(var o:db.list("SELECT offer_id FROM asp_matching_offer_member WHERE request_id=?",request))cancelOffer(number(o.get("offer_id")),"declined");db.update("UPDATE asp_matching_request SET status='cancelled',version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=? AND status IN ('waiting','offered')",request);return reference(json,"requestId",request,"cancelled");}
        long room=id(in,"roomId");var located=load(room);long unit=number(located.get("unit_id"));db.lock("room-unit:"+unit);expire(unit);var r=load(room);long host=number(r.get("host_account_id"));
        if(code.equals("room.apply")){openUnit(unit);free(unit,a);if(db.count("SELECT count(*) FROM asp_recruitment WHERE room_id=? AND status='open' AND expires_at>CURRENT_TIMESTAMP",room)==0)throw fail("招募已关闭",409);capacity(r);eligibleTeam(r,a);long offer=offer(unit,room,List.of(host,a),Map.of());db.update("UPDATE asp_matching_offer_member SET status='accepted',answered_at=CURRENT_TIMESTAMP WHERE offer_id=? AND account_id=?",offer,a);return reference(json,"offerId",offer,"pending");}
        member(room,a);
        if(in.has("expectedVersion")&&number(r.get("version"))!=in.get("expectedVersion").asLong())throw fail("房间状态已变化，请刷新后继续",409);
        if(code.equals("room.encourage")){interaction(room,a,"encourage",text(in,"message",100));return reference(json,"roomId",room,"encouraged");}
        if(code.equals("room.ready")){mutable(r);db.update("UPDATE asp_team_room_member SET ready=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE room_id=? AND account_id=? AND status='active'",in.path("ready").asBoolean(),room,a);refresh(room);interaction(room,a,"ready",in.path("ready").asBoolean()?"已准备好，期待和你并肩上场！":"正在调整准备状态");return reference(json,"roomId",room,"updated");}
        if(host!=a&&!code.equals("room.leave"))throw fail("请由房主办理",403);
        if(code.equals("room.announce")){mutable(r);db.update("UPDATE asp_team_room SET announcement=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",text(in,"message",1000),room);interaction(room,a,"announcement",text(in,"message",500));return reference(json,"roomId",room,"updated");}
        if(code.equals("room.recruit")){openUnit(unit);mutable(r);capacity(r);db.update("INSERT INTO asp_recruitment(id,room_id,creator_account_id,message,status,expires_at) VALUES (?,?,?,?,'open',CURRENT_TIMESTAMP+INTERVAL '1 day') ON CONFLICT(room_id) WHERE status='open' DO UPDATE SET message=excluded.message,expires_at=excluded.expires_at,version=asp_recruitment.version+1,update_time=CURRENT_TIMESTAMP",nextId(),room,a,text(in,"message",500));return reference(json,"roomId",room,"recruiting");}
        if(code.equals("room.prepare")){openUnit(unit);mutable(r);var u=openUnit(unit);if(db.count("SELECT count(*) FROM asp_team_room_member WHERE room_id=? AND status='active' AND ready",room)!=number(u.get("min_members")))throw fail("请集齐成员，并由每人确认准备后继续",409);long registration=registrations.prepare(room,ActionContext.current().requestKey());db.update("UPDATE asp_team_room SET registration_id=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",registration,room);db.update("UPDATE asp_recruitment SET status='closed',version=version+1 WHERE room_id=? AND status='open'",room);return reference(json,"registrationId",registration,"draft");}
        if(code.equals("room.transfer")||code.equals("room.leave")){if(r.get("registration_id")!=null)throw fail("已生成报名，请先在报名详情交接管理责任；本场名单在报名详情办理",409);Long target=optionalId(in,"newHostAccountId");if(host==a){long others=db.count("SELECT count(*) FROM asp_team_room_member WHERE room_id=? AND status='active' AND account_id<>?",room,a);if(others>0){if(target==null||target==a)throw fail("请选择一名当前成员接任房主",409);member(room,target);if(r.get("team_id")!=null&&db.count("SELECT count(*) FROM asp_team t JOIN asp_account a ON a.person_id=t.captain_person_id WHERE t.id=? AND a.id=?",r.get("team_id"),target)==0)throw fail("长期小队参赛请先交接小队队长，再交接本场房主",409);db.update("UPDATE asp_team_room SET host_account_id=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=?",target,room);}else if(code.equals("room.transfer"))throw fail("房间还没有其他成员",409);else db.update("UPDATE asp_team_room SET status='closed',version=version+1 WHERE id=?",room);}if(code.equals("room.leave")){db.update("UPDATE asp_team_room_member SET status='left',ready=false,left_at=CURRENT_TIMESTAMP,version=version+1 WHERE room_id=? AND account_id=? AND status='active'",room,a);db.update("UPDATE asp_recruitment SET status='closed',version=version+1 WHERE room_id=? AND status='open'",room);for(var o:db.list("SELECT id FROM asp_matching_offer WHERE room_id=? AND status='pending'",room))cancelOffer(number(o.get("id")),"declined");refresh(room);}return reference(json,"roomId",room,code.equals("room.leave")?"left":"transferred");}
        throw fail("不支持的房间操作",400);
    }
    public JsonNode home(){long a=account();var out=json.createObjectNode();out.put("accountId",Long.toString(a));out.set("rooms",safeJson(json,db.list("SELECT r.*,u.name AS unit_name,e.name AS event_name,t.name AS type_name,t.max_members,(SELECT count(*) FROM asp_team_room_member m WHERE m.room_id=r.id AND m.status='active') AS member_count FROM asp_team_room r JOIN asp_competition_unit u ON u.id=r.unit_id JOIN asp_event e ON e.id=u.event_id JOIN asp_competition_type t ON t.id=r.competition_type_id WHERE r.id IN (SELECT room_id FROM asp_team_room_member WHERE account_id=? AND status='active') AND r.status<>'closed' ORDER BY r.create_time DESC",a)));out.set("offers",safeJson(json,db.list("SELECT o.id,o.unit_id,o.room_id,o.expires_at,m.status AS my_status,u.name AS unit_name,e.name AS event_name FROM asp_matching_offer o JOIN asp_matching_offer_member m ON m.offer_id=o.id JOIN asp_competition_unit u ON u.id=o.unit_id JOIN asp_event e ON e.id=u.event_id WHERE m.account_id=? AND o.status='pending' AND o.expires_at>CURRENT_TIMESTAMP ORDER BY o.create_time DESC",a)));out.set("requests",safeJson(json,db.list("SELECT id,unit_id,room_id,status,expires_at FROM asp_matching_request WHERE account_id=? AND status IN ('waiting','offered') AND expires_at>CURRENT_TIMESTAMP",a)));return out;}
    public JsonNode options(long unit){var u=openUnit(unit);var result=json.createObjectNode();result.set("unit",safeJson(json,u));result.set("recruitments",safeJson(json,db.list("SELECT r.id AS room_id,r.name,r.team_id,p.message,p.expires_at,COALESCE(d.nickname,'球友') AS host_nickname,COALESCE(d.avatar_style,'mint') AS avatar_style,d.avatar_file_id,r.host_account_id,(SELECT count(*) FROM asp_team_room_member m WHERE m.room_id=r.id AND m.status='active') AS member_count,t.max_members FROM asp_recruitment p JOIN asp_team_room r ON r.id=p.room_id JOIN asp_competition_type t ON t.id=r.competition_type_id LEFT JOIN asp_profile_display d ON d.account_id=r.host_account_id WHERE r.unit_id=? AND p.status='open' AND p.expires_at>CURRENT_TIMESTAMP AND r.status='forming' ORDER BY p.create_time DESC LIMIT 50",unit)));return result;}
    public JsonNode detail(long room){long a=account();member(room,a);var r=load(room);var out=json.createObjectNode();out.put("accountId",Long.toString(a));out.set("room",safeJson(json,r));out.set("members",safeJson(json,db.list("SELECT m.account_id,m.ready,m.version,COALESCE(d.nickname,'球友') AS nickname,COALESCE(d.avatar_style,'mint') AS avatar_style,d.avatar_file_id,COALESCE(g.points,0) AS points,x.title_code,h.title AS title FROM asp_team_room_member m JOIN asp_team_room r ON r.id=m.room_id JOIN asp_competition_unit u ON u.id=r.unit_id LEFT JOIN asp_profile_display d ON d.account_id=m.account_id LEFT JOIN asp_growth_profile g ON g.owner_type='person' AND g.owner_id=m.person_id AND g.sport_id=u.sport_id LEFT JOIN asp_title_equipment x ON x.owner_type='person' AND x.owner_id=m.person_id AND x.sport_id=u.sport_id LEFT JOIN asp_honor h ON h.id=x.honor_id AND h.status='verified' WHERE m.room_id=? AND m.status='active' ORDER BY m.joined_at",room)));var rule=growthPolicies.current(number(r.get("sport_id")));for(var m:out.path("members")){var node=(com.fasterxml.jackson.databind.node.ObjectNode)m;int rank=rule.rank(m.path("points").asLong());node.put("rank_index",rank);node.put("rank_name",rule.rankNames().get(rank));}out.set("interactions",safeJson(json,db.list("SELECT i.kind,i.text,i.create_time,COALESCE(d.nickname,'球友') AS nickname FROM asp_room_interaction i LEFT JOIN asp_profile_display d ON d.account_id=i.account_id WHERE i.room_id=? ORDER BY i.create_time DESC LIMIT 30",room)));return out;}
    private Map<String,Object> openUnit(long unit){var u=db.one("SELECT u.*,t.name AS type_name,t.status AS type_status,t.capability_status FROM asp_competition_unit u JOIN asp_competition_type t ON t.id=u.competition_type_id WHERE u.id=? AND u.status='open'",unit);if(u==null||!"active".equals(u.get("type_status"))||!"manual".equals(u.get("capability_status")))throw fail("该比赛类型尚未开放组队和报名",409);if(number(u.get("max_members"))!=2||!"pair".equals(u.get("entry_type")))throw fail("单打请直接本人报名；目前房间开放羽毛球双打",409);var e=events.publicGate(number(u.get("event_id"))).orElseThrow(()->fail("当前赛事未开放",409));if(!events.acceptsNewBusiness(number(u.get("event_id")))||!"normal".equals(e.holdingStatus())||e.registrationClosesAt()!=null&&!OffsetDateTime.now().isBefore(e.registrationClosesAt()))throw fail("当前赛事不再接收新的组队报名",409);return u;}
    private Map<String,Object> load(long room){var r=db.one("SELECT r.*,t.max_members,t.min_members,t.name AS type_name,u.event_id,u.sport_id,u.name AS unit_name,e.name AS event_name,lt.name AS team_name,th.title AS team_title FROM asp_team_room r JOIN asp_competition_type t ON t.id=r.competition_type_id JOIN asp_competition_unit u ON u.id=r.unit_id JOIN asp_event e ON e.id=u.event_id LEFT JOIN asp_team lt ON lt.id=r.team_id LEFT JOIN asp_title_equipment tx ON tx.owner_type='team' AND tx.owner_id=r.team_id AND tx.sport_id=u.sport_id LEFT JOIN asp_honor th ON th.id=tx.honor_id AND th.status='verified' WHERE r.id=?",room);if(r==null)throw fail("房间不存在",404);return r;}
    private long person(long a){var p=db.one("SELECT a.person_id FROM asp_account a JOIN asp_person p ON p.id=a.person_id WHERE a.id=? AND a.status='active' AND p.status='active'",a);if(p==null)throw fail("请先补齐本人参赛资料，再进入参赛房间",409);return number(p.get("person_id"));}
    private void member(long room,long a){if(db.count("SELECT count(*) FROM asp_team_room_member WHERE room_id=? AND account_id=? AND status='active'",room,a)==0)throw fail("房间详情仅向当前成员开放",403);}
    private void free(long unit,long a){person(a);if(db.count("SELECT count(*) FROM asp_team_room_member WHERE unit_id=? AND account_id=? AND status='active'",unit,a)>0)throw fail("你已在这个项目的参赛房间中",409);if(db.count("SELECT count(*) FROM asp_registration_member WHERE unit_id=? AND account_id=? AND occupying",unit,a)>0)throw fail("你已正式报名这个项目",409);if(db.count("SELECT count(*) FROM asp_matching_offer_member m JOIN asp_matching_offer o ON o.id=m.offer_id WHERE o.unit_id=? AND m.account_id=? AND o.status='pending' AND o.expires_at>CURRENT_TIMESTAMP",unit,a)>0)throw fail("你还有一份组队邀请待处理",409);}
    private void mutable(Map<String,Object> r){if(!Set.of("forming","ready").contains(r.get("status"))||r.get("registration_id")!=null)throw fail("房间已进入报名阶段，请在报名详情办理",409);}
    private void capacity(Map<String,Object> r){mutable(r);long room=number(r.get("id"));long occupied=db.count("SELECT count(*) FROM asp_team_room_member WHERE room_id=? AND status='active'",room);long reserved=db.count("SELECT count(*) FROM asp_matching_offer WHERE room_id=? AND status='pending' AND expires_at>CURRENT_TIMESTAMP",room);if(occupied+reserved>=number(r.get("max_members")))throw fail("房间席位已满或正在等待邀请确认",409);}
    private void eligibleTeam(Map<String,Object> r,long a){if(r.get("team_id")!=null&&db.count("SELECT count(*) FROM asp_team_member WHERE team_id=? AND person_id=? AND status='active'",r.get("team_id"),person(a))==0)throw fail("这是长期队伍参赛房间，请先申请加入该队，或选择临时搭档房间",409);}
    private long create(long unit,long type,long host,Long team,String name){long room=nextId();db.update("INSERT INTO asp_team_room(id,unit_id,competition_type_id,host_account_id,team_id,name,status) VALUES (?,?,?,?,?,?,'forming')",room,unit,type,host,team,name);join(room,unit,host);return room;}
    private void join(long room,long unit,long a){db.update("INSERT INTO asp_team_room_member(id,room_id,unit_id,account_id,person_id,status,ready,joined_at) VALUES (?,?,?,?,?,'active',false,CURRENT_TIMESTAMP)",nextId(),room,unit,a,person(a));interaction(room,a,"welcome","欢迎加入！一起认真准备，也一起享受比赛。");}
    private void interaction(long room,long a,String kind,String text){String key=ActionContext.current().requestKey()+":"+kind+":"+room;if(key.length()>128)key=UUID.randomUUID().toString();db.update("INSERT INTO asp_room_interaction(id,room_id,account_id,kind,text,request_key) VALUES (?,?,?,?,?,?) ON CONFLICT(account_id,request_key) DO NOTHING",nextId(),room,a,kind,text,key);}
    private void refresh(long room){db.update("UPDATE asp_team_room r SET status=CASE WHEN (SELECT count(*) FROM asp_team_room_member m WHERE m.room_id=r.id AND m.status='active' AND m.ready)=(SELECT max_members FROM asp_competition_type t WHERE t.id=r.competition_type_id) THEN 'ready' ELSE 'forming' END,version=version+1,update_time=CURRENT_TIMESTAMP WHERE r.id=? AND r.status IN ('forming','ready')",room);}
    private JsonNode queue(JsonNode in,long a){long unit=id(in,"unitId");db.lock("room-unit:"+unit);expire(unit);openUnit(unit);Long room=optionalId(in,"roomId");if(room!=null){var r=load(room);if(number(r.get("unit_id"))!=unit||number(r.get("host_account_id"))!=a)throw fail("请由本场房主发起补员",403);capacity(r);}else free(unit,a);long request=nextId();var prefs=json.createObjectNode();prefs.put("timePreference",in.path("timePreference").asText("any"));db.update("INSERT INTO asp_matching_request(id,unit_id,account_id,room_id,preferences,status,expires_at) VALUES (?,?,?,?,?::jsonb,'waiting',CURRENT_TIMESTAMP+INTERVAL '30 minutes') ON CONFLICT(unit_id,account_id) WHERE status IN ('waiting','offered') DO UPDATE SET room_id=CASE WHEN asp_matching_request.status='waiting' THEN excluded.room_id ELSE asp_matching_request.room_id END,preferences=excluded.preferences,expires_at=excluded.expires_at",request,unit,a,room,prefs.toString());var own=db.one("SELECT id,status FROM asp_matching_request WHERE unit_id=? AND account_id=? AND status IN ('waiting','offered')",unit,a);request=number(own.get("id"));if("offered".equals(own.get("status")))return reference(json,"requestId",request,"offered");
        for(var candidate:db.list("SELECT * FROM asp_matching_request WHERE unit_id=? AND account_id<>? AND status='waiting' AND expires_at>CURRENT_TIMESTAMP AND (preferences->>'timePreference'=? OR preferences->>'timePreference'='any' OR ?='any') ORDER BY create_time FOR UPDATE",unit,a,prefs.path("timePreference").asText(),prefs.path("timePreference").asText())){Long otherRoom=candidate.get("room_id")==null?null:number(candidate.get("room_id"));if(room!=null&&otherRoom!=null)continue;long other=number(candidate.get("account_id"));Long target=room!=null?room:otherRoom;try{if(target!=null){capacity(load(target));eligibleTeam(load(target),room==null?a:other);}else{free(unit,other);}}catch(org.dromara.common.core.exception.ServiceException ex){continue;}long offer=offer(unit,target,List.of(a,other),Map.of(a,request,other,number(candidate.get("id"))));return reference(json,"offerId",offer,"pending");}return reference(json,"requestId",request,"waiting");}
    private long offer(long unit,Long room,List<Long> accounts,Map<Long,Long> requests){long offer=nextId();db.update("INSERT INTO asp_matching_offer(id,unit_id,room_id,status,expires_at) VALUES (?,?,?,'pending',CURRENT_TIMESTAMP+INTERVAL '120 seconds')",offer,unit,room);for(long a:accounts){db.update("INSERT INTO asp_matching_offer_member(id,offer_id,account_id,request_id,status) VALUES (?,?,?,?,'pending')",nextId(),offer,a,requests.get(a));if(requests.get(a)!=null)db.update("UPDATE asp_matching_request SET status='offered',version=version+1 WHERE id=? AND status='waiting'",requests.get(a));}return offer;}
    private JsonNode answer(JsonNode in,long a){long offer=id(in,"offerId");var located=db.one("SELECT o.* FROM asp_matching_offer o JOIN asp_matching_offer_member m ON m.offer_id=o.id WHERE o.id=? AND m.account_id=?",offer,a);if(located==null)throw fail("邀请不存在",404);long unit=number(located.get("unit_id"));db.lock("room-unit:"+unit);expire(unit);var o=db.one("SELECT * FROM asp_matching_offer WHERE id=?",offer);if(!"pending".equals(o.get("status")))throw fail("邀请已结束，请返回重新匹配",409);String answer=text(in,"answer",16);if(!Set.of("accept","decline").contains(answer))throw fail("请选择接受或拒绝",400);if(answer.equals("decline")){cancelOffer(offer,"declined");return reference(json,"offerId",offer,"declined");}openUnit(unit);db.update("UPDATE asp_matching_offer_member SET status='accepted',answered_at=CURRENT_TIMESTAMP,version=version+1 WHERE offer_id=? AND account_id=? AND status='pending'",offer,a);if(db.count("SELECT count(*) FROM asp_matching_offer_member WHERE offer_id=? AND status<>'accepted'",offer)>0)return reference(json,"offerId",offer,"waiting_partner");var members=db.list("SELECT account_id FROM asp_matching_offer_member WHERE offer_id=? ORDER BY create_time,id",offer);Long room=o.get("room_id")==null?null:number(o.get("room_id"));if(room==null){long host=number(members.get(0).get("account_id"));for(var m:members)ensureCanJoin(unit,number(m.get("account_id")),null);var u=openUnit(unit);room=create(unit,number(u.get("competition_type_id")),host,null,"新搭档 · 一起上场");}var r=load(room);mutable(r);for(var m:members){long target=number(m.get("account_id"));if(db.count("SELECT count(*) FROM asp_team_room_member WHERE room_id=? AND account_id=? AND status='active'",room,target)==0){ensureCanJoin(unit,target,room);eligibleTeam(r,target);if(db.count("SELECT count(*) FROM asp_team_room_member WHERE room_id=? AND status='active'",room)>=number(r.get("max_members")))throw fail("房间席位发生变化，请重新匹配",409);join(room,unit,target);}}db.update("UPDATE asp_matching_offer SET status='accepted',room_id=?,version=version+1 WHERE id=?",room,offer);db.update("UPDATE asp_matching_request SET status='accepted',version=version+1 WHERE id IN (SELECT request_id FROM asp_matching_offer_member WHERE offer_id=?)",offer);db.update("UPDATE asp_recruitment SET status='filled',version=version+1 WHERE room_id=? AND status='open'",room);refresh(room);return reference(json,"roomId",room,"joined");}
    private void ensureCanJoin(long unit,long a,Long room){person(a);if(db.count("SELECT count(*) FROM asp_team_room_member WHERE unit_id=? AND account_id=? AND status='active'",unit,a)>0)throw fail("成员已进入其他房间",409);if(db.count("SELECT count(*) FROM asp_registration_member WHERE unit_id=? AND account_id=? AND occupying",unit,a)>0)throw fail("成员已正式报名",409);}
    private void expire(long unit){for(var r:db.list("SELECT id FROM asp_matching_offer WHERE unit_id=? AND status='pending' AND expires_at<=CURRENT_TIMESTAMP",unit))cancelOffer(number(r.get("id")),"expired");db.update("UPDATE asp_matching_request SET status='expired',version=version+1 WHERE unit_id=? AND status='waiting' AND expires_at<=CURRENT_TIMESTAMP",unit);}
    private void cancelOffer(long offer,String status){if(db.update("UPDATE asp_matching_offer SET status=?,version=version+1 WHERE id=? AND status='pending'",status,offer)==1)db.update("UPDATE asp_matching_request SET status=CASE WHEN expires_at>CURRENT_TIMESTAMP THEN 'waiting' ELSE 'expired' END,version=version+1 WHERE id IN (SELECT request_id FROM asp_matching_offer_member WHERE offer_id=?) AND status='offered'",offer);}
}
